import "server-only";
import { createHash } from "node:crypto";
import type { AuditResult, UserContext } from "@/types/insurance";

/**
 * Short-lived, in-memory cache of finished audits, keyed by the exact PDF
 * bytes (SHA-256) plus the household context. Identical requests — most often
 * the demo households, whose PDFs are generated byte-for-byte the same — are
 * answered instantly from a real earlier Gemini run instead of spending quota
 * again. Results are labelled as cached in the response (`meta.cachedAt`).
 *
 * Per server instance only (a serverless cold start starts empty), which is
 * enough to absorb bursts such as a jury opening the demo at the same time.
 */

const TTL_MS = 6 * 60 * 60 * 1000;
const MAX_ENTRIES = 100;

export interface CachedAudit {
  audit: AuditResult;
  model: string;
  at: number;
}

const store = new Map<string, CachedAudit>();

export function auditCacheKey(fileHashes: string[], context: UserContext): string {
  return createHash("sha256")
    .update(JSON.stringify({ v: 1, files: [...fileHashes].sort(), context }))
    .digest("hex");
}

export function getCachedAudit(key: string): CachedAudit | null {
  const hit = store.get(key);
  if (!hit) return null;
  if (Date.now() - hit.at > TTL_MS) {
    store.delete(key);
    return null;
  }
  return hit;
}

export function setCachedAudit(key: string, entry: CachedAudit): void {
  if (!store.has(key) && store.size >= MAX_ENTRIES) {
    const oldest = store.keys().next().value;
    if (oldest !== undefined) store.delete(oldest);
  }
  store.set(key, entry);
}

/** For tests. */
export function clearAuditCache(): void {
  store.clear();
}
